/** SVG markup for a vendored Lucide icon; throws for a name not vendored. */
export function lucide(name) {
  const svg = LUCIDE_ICONS[name];
  if (!svg) throw new Error(`Lucide icon not vendored: ${name}`);
  return svg;
}
